SELECT status, customer_id, ROUND((100 * SUM(CASE WHEN account_type = 'SAVINGS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_savings, MAX(opened_date) AS latest_opened_date, SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END) AS credit_count FROM accounts GROUP BY status, customer_id HAVING credit_count > 78 ORDER BY credit_count ASC, status ASC
